import 'dart:ffi';
import 'dart:io';
import 'dart:typed_data';
import 'package:ffi/ffi.dart';
import 'package:sound_dart/sound_dart.dart';

// Every loaded module named [name] (Windows: the process module list).
List<String> windowsModules(String name) {
  final kernel32 = DynamicLibrary.open('kernel32.dll');
  final process = kernel32.lookupFunction<IntPtr Function(), int Function()>('GetCurrentProcess');
  final enumModules = kernel32.lookupFunction<Int32 Function(IntPtr, Pointer<IntPtr>, Uint32, Pointer<Uint32>), int Function(int, Pointer<IntPtr>, int, Pointer<Uint32>)>('K32EnumProcessModules');
  final fileName = kernel32.lookupFunction<Uint32 Function(IntPtr, Pointer<Utf16>, Uint32), int Function(int, Pointer<Utf16>, int)>('GetModuleFileNameW');
  const capacity = 4096, pathCapacity = 32768;
  final modules = calloc<IntPtr>(capacity), needed = calloc<Uint32>(), path = calloc<Uint16>(pathCapacity).cast<Utf16>();
  try {
    if (enumModules(process(), modules, capacity * sizeOf<IntPtr>(), needed) == 0) throw StateError('K32EnumProcessModules failed');
    final count = needed.value ~/ sizeOf<IntPtr>();
    if (count > capacity) throw StateError('module list truncated: $count');
    final found = <String>[];
    for (var i = 0; i < count; i++) {
      final length = fileName(modules[i], path, pathCapacity);
      if (length == 0 || length >= pathCapacity) throw StateError('GetModuleFileNameW failed');
      final value = path.toDartString(length: length);
      if (value.split(r'\').last.toLowerCase() == name) found.add(value);
    }
    return found;
  } finally {
    calloc.free(modules); calloc.free(needed); calloc.free(path);
  }
}

String windowsPath(String path) => (path.startsWith(r'\\?\') ? path.substring(4) : path).toLowerCase();

// The exact bundled file, and only it, is the loaded library.
void expectExactLibrary(String expected) {
  if (Platform.isWindows) {
    final modules = windowsModules('sound_cli.dll');
    if (modules.length != 1 || windowsPath(modules.single) != windowsPath(expected)) throw StateError('unexpected native module: $modules');
    return;
  }
  final mappings = File('/proc/self/maps').readAsLinesSync().where((line) => line.contains('libsound_cli.so')).toList();
  if (mappings.isEmpty || mappings.any((line) => !line.endsWith(' $expected'))) throw StateError('unexpected native mapping: $mappings');
}

Uint8List wav(List<int> samples) {
  final data = samples.length * 2;
  final wav = Uint8List(44 + data); final bytes = ByteData.sublistView(wav);
  void ascii(int offset, String value) => wav.setRange(offset, offset + value.length, value.codeUnits);
  ascii(0,'RIFF'); bytes.setUint32(4,36 + data,Endian.little); ascii(8,'WAVE'); ascii(12,'fmt ');
  bytes.setUint32(16,16,Endian.little); bytes.setUint16(20,1,Endian.little); bytes.setUint16(22,1,Endian.little);
  bytes.setUint32(24,8000,Endian.little); bytes.setUint32(28,16000,Endian.little); bytes.setUint16(32,2,Endian.little); bytes.setUint16(34,16,Endian.little);
  ascii(36,'data'); bytes.setUint32(40,data,Endian.little);
  for (var i = 0; i < samples.length; i++) { bytes.setInt16(44 + 2 * i, samples[i], Endian.little); }
  return wav;
}

// Device-free C ABI: decode-to-PCM, null handles and player lifecycle.
void checkAbi(String path) {
  final lib = DynamicLibrary.open(path);
  final decodeBytes = lib.lookupFunction<Pointer<Void> Function(Pointer<Uint8>, Size, Pointer<Utf8>), Pointer<Void> Function(Pointer<Uint8>, int, Pointer<Utf8>)>('sound_decode_bytes');
  final decodedLen = lib.lookupFunction<Int64 Function(Pointer<Void>), int Function(Pointer<Void>)>('sound_decoded_len');
  final decodedChannels = lib.lookupFunction<Int32 Function(Pointer<Void>), int Function(Pointer<Void>)>('sound_decoded_channels');
  final decodedRate = lib.lookupFunction<Int32 Function(Pointer<Void>), int Function(Pointer<Void>)>('sound_decoded_rate');
  final decodedCopy = lib.lookupFunction<IntPtr Function(Pointer<Void>, Size, Pointer<Int16>, Size), int Function(Pointer<Void>, int, Pointer<Int16>, int)>('sound_decoded_copy');
  final decodedFree = lib.lookupFunction<Void Function(Pointer<Void>), void Function(Pointer<Void>)>('sound_decoded_free');
  final lastError = lib.lookupFunction<Pointer<Utf8> Function(), Pointer<Utf8> Function()>('sound_last_error');
  final playerNew = lib.lookupFunction<Pointer<Void> Function(), Pointer<Void> Function()>('sound_player_new');
  final playerFree = lib.lookupFunction<Void Function(Pointer<Void>), void Function(Pointer<Void>)>('sound_player_free');
  final voiceState = lib.lookupFunction<Int32 Function(Pointer<Void>, Uint64), int Function(Pointer<Void>, int)>('sound_voice_state');
  const samples = [1000, -1000, 32767, -32768];
  final encoded = wav(samples);
  final input = calloc<Uint8>(encoded.length), hint = 'wav'.toNativeUtf8(allocator: calloc), out = calloc<Int16>(8), garbage = calloc<Uint8>(64);
  try {
    input.asTypedList(encoded.length).setAll(0, encoded);
    final decoded = decodeBytes(input, encoded.length, hint);
    if (decoded == nullptr) throw StateError('decode failed: ${lastError().toDartString()}');
    try {
      if (decodedLen(decoded) != 4 || decodedChannels(decoded) != 1 || decodedRate(decoded) != 8000) throw StateError('unexpected decoded format');
      if (decodedCopy(decoded, 0, out, 8) != 4) throw StateError('short PCM copy');
      final pcm = out.asTypedList(4).toList();
      if (pcm.join(',') != samples.join(',')) throw StateError('PCM mismatch: $pcm');
      if (decodedCopy(decoded, 2, out, 8) != 2 || decodedCopy(decoded, 4, out, 8) != 0) throw StateError('copy bounds');
    } finally {
      decodedFree(decoded);
    }
    if (decodedLen(nullptr) != -1 || decodedChannels(nullptr) != -1 || decodedRate(nullptr) != -1 || decodedCopy(nullptr, 0, out, 8) != -1) throw StateError('null handle contract');
    decodedFree(nullptr);
    if (decodeBytes(garbage, 64, nullptr) != nullptr || lastError().toDartString().isEmpty) throw StateError('garbage decoded');
    // Creating a player resolves the OS audio library; no device is opened.
    final player = playerNew();
    if (player == nullptr) throw StateError('sound_player_new failed: ${lastError().toDartString()}');
    if (voiceState(player, 42) != -1 || voiceState(nullptr, 42) != -1) throw StateError('unknown voice contract');
    playerFree(player);
    playerFree(nullptr);
  } finally {
    calloc.free(input); calloc.free(hint); calloc.free(out); calloc.free(garbage);
  }
}

Future<void> main() async {
  final expected = File(Platform.environment['SOUND_DART_LIB']!).resolveSymbolicLinksSync();
  final backend = Sound.backend; await backend.initialize();
  if (backend.name != 'ffi') throw StateError('native backend did not load');
  expectExactLibrary(expected);
  checkAbi(expected);
  final playback = await Sound.load(SoundSource.bytes(wav([0, 0, 0, 0]), format:'wav'));
  if (playback.state != PlaybackState.idle) throw StateError('unexpected initial state');
  await playback.dispose();
  if (playback.state != PlaybackState.disposed) throw StateError('disposal failed');
  await Sound.reset();
  expectExactLibrary(expected);
  print('Exact native library loaded ($expected); PCM decode, null-handle ABI, player initialization, idle load and disposal passed (no audio device opened, no playback)');
}
